/*!
 * data/banco.js — banco de preguntas del autotest de FC (temas 1–6) y metadatos de los temas.
 * Exporta FC.BANK, FC.TOPICS, FC.TOPIC_IDS y FC.GENERAL_MIX.
 */
(function (FC) {
  "use strict";
/* Preguntas (formato de cada elemento):
   t: tema; q: enunciado; o: opciones (el orden se baraja al mostrarlas); a: índice correcto;
   e: explicación; w: explicación específica de por qué una opción incorrecta lo es (opcional).
   El código, los bits y las fórmulas van entre `acentos graves` y se muestran en fuente monoespaciada. */
const BANK = [
/* ---------------- TEMA 1 · Introducción ---------------- */
{t:1,q:"¿Cuáles son los niveles de descripción del computador, de dentro hacia fuera?",o:["Hardware, sistema operativo, aplicaciones y servicios de red","Aplicaciones, hardware, sistema operativo y servicios de red","Sistema operativo, hardware, servicios de red y aplicaciones","Hardware, aplicaciones, compilador y red"],a:0,e:"Cada nivel se apoya en el inferior y oculta sus detalles al superior: hardware → SO → aplicaciones → servicios de red."},
{t:1,q:"En el esquema de Von Neumann, la CPU está formada por…",o:["La unidad de control y el camino de datos","La memoria principal y la E/S","La ALU y la memoria caché","El bus de datos y el bus de direcciones"],a:0,e:"CPU = unidad de control (lee, decodifica y genera señales de control) + camino de datos (ALU y registros). Los otros dos bloques de Von Neumann son la memoria principal y la E/S."},
{t:1,q:"Sobre el esquema de Von Neumann es cierto que…",o:["Es una visión de alto nivel de la arquitectura de un ordenador, válida hoy","Está en desuso desde la aparición del microprocesador","Describe el interior del microprocesador transistor a transistor","Separa físicamente la memoria de instrucciones de la de datos"],a:0,e:"Sigue siendo válido: la CPU trae instrucciones y datos de la misma memoria principal (concepto de programa almacenado).",w:{1:"Falso: es la pregunta trampa típica. El esquema sigue siendo válido.",3:"Al contrario: instrucciones y datos están en la misma memoria principal."}},
{t:1,q:"La unidad de control…",o:["Lee las instrucciones de memoria, las decodifica y genera las señales de control","Realiza las operaciones aritméticas con los operandos","Almacena los datos y las instrucciones del programa","Traduce el programa de alto nivel a ensamblador"],a:0,e:"La UC decodifica (con circuitos decodificadores) y gobierna al resto. Las operaciones las hace el camino de datos (ALU).",w:{1:"Eso lo hace el camino de datos (ALU y registros).",3:"Eso es el compilador, un programa, no un bloque hardware."}},
{t:1,q:"¿Qué determina el ancho del bus de direcciones?",o:["La capacidad máxima de memoria que se puede direccionar","La velocidad de transferencia CPU‑RAM","El número de bytes que se leen en una operación","El número de interrupciones que se pueden atender"],a:0,e:"Con n hilos se direccionan 2^n celdas de 1 byte. El bus de datos es el que influye en la velocidad de transferencia.",w:{1:"Eso depende sobre todo del bus de datos (y de su frecuencia).",2:"Eso lo marca el ancho del bus de datos."}},
{t:1,q:"Un bus de direcciones de 32 bits puede direccionar como máximo…",o:["4 GB","32 bytes","32 GB","4 MB"],a:0,e:"2^32 bytes = 2^2 · 2^30 = 4 GB (celdas de 1 byte)."},
{t:1,q:"¿Cuántos bits de bus de direcciones hacen falta para una memoria de 64 KB (celdas de 1 byte)?",o:["16","64","6","20"],a:0,e:"64 KB = 2^6 · 2^10 = 2^16 bytes → 16 bits. En general n = log2(nº de bytes)."},
{t:1,q:"Un bus de direcciones de 64 bits direcciona hasta…",o:["2^64 celdas de 1 byte","64 celdas de 1 byte","2^64 celdas de 64 bits","64 celdas de 64 bits"],a:0,e:"Cada hilo es un bit de la dirección: 2^64 direcciones distintas, cada una de una celda de 1 byte (16 EB)."},
{t:1,q:"En una lectura de memoria, ¿qué buses intervienen?",o:["Los tres: direcciones, datos y control","Sólo el de direcciones y el de datos","Sólo el de datos","Sólo el de control"],a:0,e:"La CPU pone la dirección en el bus de direcciones, activa IOR en el de control y la memoria deja el contenido en el de datos."},
{t:1,q:"En una escritura en memoria, la CPU activa el hilo…",o:["IOW del bus de control","IOR del bus de control","IRQ del bus de datos","ACK del bus de direcciones"],a:0,e:"IOR = lectura, IOW = escritura; ambos son del bus de control.",w:{1:"IOR es la señal de lectura."}},
{t:1,q:"El bus de direcciones es…",o:["Unidireccional: la dirección la pone la CPU","Bidireccional, como el de datos","Inexistente en los PC actuales","El que transporta las instrucciones"],a:0,e:"La CPU pone la dirección; el bus de datos sí es bidireccional (se lee y se escribe por él)."},
{t:1,q:"Ordena de más rápida a más lenta: RAM, registros, disco, caché.",o:["Registros → caché → RAM → disco","Caché → registros → RAM → disco","RAM → caché → registros → disco","Registros → RAM → caché → disco"],a:0,e:"Jerarquía de memoria: más rápido = más pequeño y más caro por byte. La caché guarda copias de lo usado recientemente."},
{t:1,q:"¿Cuál de estas afirmaciones sobre la RAM y la caché es correcta?",o:["La RAM guarda instrucciones y datos y es más grande y lenta que la caché","La RAM guarda sólo datos y la caché sólo instrucciones","La caché es más grande que la RAM","La caché está siempre en el disco duro"],a:0,e:"La caché es una memoria pequeña y rápida entre CPU y RAM con copias de datos e instrucciones usados recientemente."},
{t:1,q:"La BIOS/UEFI de la placa base es un ejemplo de…",o:["Firmware","Software de aplicación","Hardware mecánico","Sistema operativo"],a:0,e:"Firmware: software de bajo nivel almacenado de forma semipermanente en una memoria programable (flash)."},
{t:1,q:"Sobre el firmware es cierto que…",o:["Puede modificarse, aunque de forma esporádica","No puede modificarse nunca","Impide hacer overclocking","Es lo mismo que el hardware"],a:0,e:"Se puede actualizar (p. ej. la BIOS), pero raramente. El overclocking se suele configurar precisamente desde la BIOS/UEFI.",w:{2:"Falso: el overclocking se configura desde la BIOS/UEFI."}},
{t:1,q:"Una variable de 4 bytes se guarda a partir de 0x3000 en little endian. ¿Dónde está su byte más significativo?",o:["0x3003","0x3000","0x3004","0x2FFD"],a:0,e:"Little endian: el byte menos significativo en la dirección más baja (D) y el más significativo en D + k − 1 = 0x3003."},
{t:1,q:"Variable de 8 bytes en 0x8AA46A23, little endian. ¿Dirección del byte más significativo?",o:["0x8AA46A2A","0x8AA46A30","0x8AA46A23","0x8AA46A31"],a:0,e:"D + 7 = 0x8AA46A23 + 7. En hexadecimal 3 + 7 = 10 = A → 0x8AA46A2A.",w:{1:"Es el error de sumar en decimal (23 + 7 = 30)."}},
{t:1,q:"En memoria, a partir de 0x00, están los bytes 00 01 02 03. Leído como entero de 4 bytes en big endian vale…",o:["0x00010203","0x03020100","0x00000003","0x01020300"],a:0,e:"Big endian: el byte de la dirección más baja es el más significativo, así que se lee en el orden «natural». En little endian sería 0x03020100."},
{t:1,q:"Los procesadores Intel x86 almacenan los datos en…",o:["Little endian","Big endian","Ninguno: no usan datos de varios bytes","Depende del sistema operativo"],a:0,e:"x86 es little endian: por eso en un editor hexadecimal los enteros aparecen «al revés» byte a byte."},
{t:1,q:"¿Cuántos estados distintos se codifican con un byte?",o:["256","8","255","128"],a:0,e:"1 byte = 8 bits → 2^8 = 256 combinaciones (de 0 a 255)."},
{t:1,q:"3 Mb/s equivalen aproximadamente a…",o:["0,375 MB/s","3 MB/s","24 MB/s","0,3 MB/s"],a:0,e:"b minúscula = bit, B mayúscula = byte: 3 / 8 = 0,375 MB/s."},
{t:1,q:"El tiempo de CPU de un programa se calcula como…",o:["Nº instrucciones × CPI / f","Nº instrucciones × f / CPI","CPI × f / Nº instrucciones","Ancho del bus × frecuencia"],a:0,e:"TCPU = N · CPI / f = N · CPI · Tciclo. La última opción es el ancho de banda."},
{t:1,q:"CPU a 40 MHz, programa de 100 millones de instrucciones, CPI = 3,6. ¿Tiempo de CPU?",o:["9 s","0,09 s","1,11 s","90 s"],a:0,e:"T = 100·10^6 × 3,6 / 40·10^6 = 360 / 40 = 9 s. (A 4 GHz serían 0,09 s.)"},
{t:1,q:"4 millones de instrucciones, 3,2 MHz y T = 5 s. ¿Cuál es el CPI?",o:["4","2,5","16","0,25"],a:0,e:"CPI = T · f / N = 5 × 3,2·10^6 / 4·10^6 = 4."},
{t:1,q:"A igualdad del resto, el tiempo de CPU…",o:["Aumenta si aumenta el CPI","Disminuye si aumenta el número de instrucciones","Aumenta si aumenta la frecuencia","Depende del ancho del bus de direcciones"],a:0,e:"TCPU crece con N y con el CPI y decrece con f. No depende del bus de direcciones."},
{t:1,q:"Bus de datos de disco de 32 bits a 10 MHz. ¿Cuánto tarda en enviar 800 MB?",o:["20 s","2,5 s","80 s","25 s"],a:0,e:"AB = 32 × 10^7 = 320 Mbit/s = 40 MB/s. Tiempo = 800 / 40 = 20 s."},
{t:1,q:"El ancho de banda de un bus es…",o:["Frecuencia del bus × ancho del bus","Frecuencia / ancho del bus","Tamaño de los datos × tiempo","Nº de hilos del bus de direcciones"],a:0,e:"AB = f × ancho (en bits/s); se divide por 8 para pasar a bytes/s. Tiempo de transmisión = tamaño / AB."},
{t:1,q:"En el chipset clásico, el puente norte (northbridge) controla…",o:["Las comunicaciones de alta velocidad: CPU ↔ RAM y tarjeta gráfica","Los puertos USB, SATA y el audio","La alimentación de la BIOS","Las ranuras PCI convencionales"],a:0,e:"El puente sur controla la E/S más lenta (SATA, USB, audio, red, PCI…). En placas actuales el northbridge está integrado en la CPU.",w:{1:"Eso es el puente sur (southbridge)."}},
{t:1,q:"La pila de botón (CR2032) de la placa base sirve para…",o:["Mantener la configuración de la BIOS (CMOS) y el reloj con el PC apagado","Alimentar el procesador cuando se va la luz","Alimentar los puertos USB","Hacer overclocking"],a:0,e:"En los ejercicios aparece como «alimentación eléctrica de la BIOS»."},
{t:1,q:"¿Qué ranura de la placa base se usa normalmente para la tarjeta gráfica?",o:["PCI Express x16","PCI Express x1","PCI convencional","SATA"],a:0,e:"PCIe x16 es la de máximo ancho de banda (16 carriles). Las x1 son cortas, para red, sonido…"},
{t:1,q:"Los conectores SATA…",o:["Conectan discos y unidades ópticas con un bus de datos serie","Conectan discos con un bus paralelo de 40 pines","Son la salida de vídeo analógica","Alimentan la placa base"],a:0,e:"SATA = Serial ATA (conector en «L» de 7 pines). El IDE/PATA es el paralelo de 40 pines.",w:{1:"Ése es IDE/PATA."}},
{t:1,q:"El conector de alimentación principal ATX de la placa tiene…",o:["24 pines (antes 20)","4 pines","7 pines","40 pines"],a:0,e:"El de 4 u 8 pines (ATX12V/EPS) alimenta los reguladores de voltaje de la CPU."},
{t:1,q:"El conector VGA es…",o:["Una salida de vídeo analógica (D-sub de 15 pines)","Una salida de vídeo digital con audio","Un puerto para el teclado","Un puerto de red"],a:0,e:"DVI, HDMI y DisplayPort son digitales (HDMI y DP llevan audio)."},
{t:1,q:"Sobre el overclocking es VERDADERO que…",o:["Puede disminuir la vida útil de la CPU al aumentar su temperatura","Se hace específicamente sobre el northbridge","Es independiente de la refrigeración","Afecta principalmente al firmware"],a:0,e:"Más frecuencia y voltaje → más calor (P ∝ V²·f). Depende totalmente de la refrigeración. El firmware sólo sirve para configurarlo.",w:{1:"Falso: se hace sobre la CPU (o GPU, RAM).",2:"Falso: depende totalmente de la refrigeración.",3:"Falso: lo que cambia es la frecuencia y el voltaje del hardware."}},
{t:1,q:"Una CPU con reloj base de 100 MHz y multiplicador 42 funciona a…",o:["4,2 GHz","142 MHz","420 MHz","42 GHz"],a:0,e:"f = BCLK × multiplicador = 100 MHz × 42 = 4200 MHz."},
{t:1,q:"El primer computador electrónico programable fue…",o:["ENIAC (1943–46)","EDVAC (1952)","IBM System/360","Intel 4004"],a:0,e:"ENIAC: 18 000 válvulas, 30 t, se programaba cableando. EDVAC fue la primera máquina de programa almacenado."},
{t:1,q:"¿Qué máquina introdujo el concepto de ISA (familia de máquinas compatibles)?",o:["IBM System/360 (1964)","PDP-8 (1965)","CDC 6600","Apple II"],a:0,e:"2.ª generación (transistores). El PDP-8 fue el primer minicomputador; el CDC 6600, el primer supercomputador."},
{t:1,q:"La tecnología de la primera generación de computadores era…",o:["Válvulas de vacío","Transistores","Circuitos integrados","Microprocesadores"],a:0,e:"1.ª válvulas, 2.ª transistor (1947, Bell), 3.ª circuito integrado, 4.ª microprocesador (Intel 4004, 1971)."},
{t:1,q:"El primer microprocesador fue…",o:["El Intel 4004 (1971)","El Pentium 4","El Intel 8088","El Cray-1"],a:0,e:"2300 transistores y unos 740 kHz. El IBM PC (1981) usó el 8088."},
{t:1,q:"¿A quién se considera la primera programadora de la historia?",o:["Ada Lovelace","Margaret Hamilton","Hedy Lamarr","Dorothy Vaughan"],a:0,e:"Diseñó un algoritmo para la máquina analítica de Babbage. Hamilton acuñó «ingeniería del software»; Lamarr patentó el salto de frecuencia."},
{t:1,q:"¿Por qué desde 2005 todos los procesadores comerciales son multinúcleo?",o:["Para seguir mejorando el rendimiento sin subir la frecuencia, ahorrando energía","Porque son más fáciles de programar","Porque así se elimina la memoria caché","Para poder usar buses de direcciones de 128 bits"],a:0,e:"También reducen el tiempo de verificación y mejoran la fiabilidad del diseño. El problema: son más difíciles de programar (programación paralela).",w:{1:"Al contrario: exigen programación paralela."}},
/* ---------------- TEMA 2 · Representación de la información ---------------- */
{t:2,q:"¿Cuánto vale `10100)2` en decimal?",o:["20","10","40","18"],a:0,e:"1·2^4 + 0·2^3 + 1·2^2 + 0 + 0 = 16 + 4 = 20."},
{t:2,q:"¿Cuánto vale `11110,101)2` en decimal?",o:["30,625","30,5","62,625","30,101"],a:0,e:"16 + 8 + 4 + 2 = 30 y 0,5 + 0,125 = 0,625."},
{t:2,q:"77 en binario natural es…",o:["`1001101`","`1011001`","`1001110`","`111101`"],a:0,e:"Divisiones sucesivas entre 2, leyendo los restos de abajo arriba: 64 + 8 + 4 + 1 = 77."},
{t:2,q:"Para pasar la parte fraccionaria de un decimal a binario…",o:["Se multiplica sucesivamente por 2 y se toman las partes enteras en orden","Se divide sucesivamente por 2 y se toman los restos de abajo arriba","Se multiplica por 10 y se toman los restos","Se agrupan las cifras de 4 en 4"],a:0,e:"0,1875 × 2 = 0,375 → 0; × 2 = 0,75 → 0; × 2 = 1,5 → 1; 0,5 × 2 = 1,0 → 1. Resultado 0,0011.",w:{1:"Ése es el método para la parte entera."}},
{t:2,q:"0,1 decimal en binario…",o:["Es periódico (0,000110011…) y no se representa exactamente","Es exactamente 0,1","Es exactamente 0,0001","Es 0,01"],a:0,e:"Se repite «0011» para siempre: hay que cortar y eso introduce error de representación. Por eso 0,1 no es exacto en IEEE 754."},
{t:2,q:"¿Cuál es el resultado de `1011101 + 1000101` (93 + 69)?",o:["`10100010`","`10100000`","`1100010`","`11100010`"],a:0,e:"93 + 69 = 162 = 128 + 32 + 2 = 10100010."},
{t:2,q:"Multiplicar un binario por `10)2` equivale a…",o:["Añadir un cero a la derecha (desplazar a la izquierda)","Quitar el bit de la derecha","Invertir todos los bits","Sumarle 10"],a:0,e:"Desplazar k posiciones a la izquierda multiplica por 2^k: 1101010 × 10 = 11010100 (106 × 2 = 212)."},
{t:2,q:"`1100 AND 1010` es…",o:["`1000`","`1110`","`0110`","`10110`"],a:0,e:"Bit a bit: sólo vale 1 donde los dos son 1. OR daría 1110 y XOR 0110."},
{t:2,q:"En lógica (OR) 1 + 1 vale…",o:["1","10","0","2"],a:0,e:"En la suma lógica 1 + 1 = 1. En aritmética binaria 1 + 1 = 10 (0 y me llevo 1)."},
{t:2,q:"Rango de un entero sin signo de 8 bits:",o:["0 … 255","−128 … 127","−127 … 127","0 … 256"],a:0,e:"Binario natural con n bits: 0 … 2^n − 1."},
{t:2,q:"¿Qué representación de enteros tiene DOS representaciones del cero?",o:["Signo y magnitud","Complemento a 2","Sesgada (exceso 2^(n−1))","Binario natural"],a:0,e:"+0 = 0000 0000 y −0 = 1000 0000. Ni C2 ni la sesgada tienen doble cero.",w:{1:"Falso: en C2 sólo hay un cero (es la pregunta trampa típica)."}},
{t:2,q:"Rango de signo y magnitud con 8 bits:",o:["−127 … +127","−128 … +127","0 … 255","−128 … +128"],a:0,e:"−(2^(n−1) − 1) … 2^(n−1) − 1. Pierde un valor por el doble cero."},
{t:2,q:"Rango del complemento a 2 con n bits:",o:["−2^(n−1) … 2^(n−1) − 1","−(2^(n−1) − 1) … 2^(n−1) − 1","0 … 2^n − 1","−2^n … 2^n"],a:0,e:"Con 8 bits, −128 … +127. Coincide con el de la sesgada con S = 2^(n−1)."},
{t:2,q:"−8 en complemento a 2 con 8 bits es…",o:["`11111000`","`10001000`","`11110111`","`01111000`"],a:0,e:"+8 = 00001000 → invertir: 11110111 → +1: 11111000.",w:{1:"Eso es −8 en signo y magnitud.",2:"Te falta sumar 1 (eso es el complemento a 1).",3:"Eso es −8 en sesgada con S = 128."}},
{t:2,q:"¿Qué valor tiene `11110110` interpretado en C2?",o:["−10","−118","246","−9"],a:0,e:"Empieza por 1 → negativo. C2: 00001001 + 1 = 00001010 = 10 → −10. Truco: −128 + 64 + 32 + 16 + 4 + 2 = −10.",w:{2:"Ése es su valor sin signo.",1:"Ése sería su valor en signo y magnitud."}},
{t:2,q:"Para calcular el opuesto (−N) de un número en C2…",o:["Se invierten todos los bits y se suma 1","Se invierte sólo el bit de signo","Se suma el sesgo","Se invierten los bits y se resta 1"],a:0,e:"Y se cumple C2(C2(N)) = N."},
{t:2,q:"¿Para qué sirve el complemento a 2?",o:["Para hacer las restas como sumas, con un único sumador","Para representar números reales","Para tener dos ceros","Para detectar errores de transmisión"],a:0,e:"A − B = A + C2(B), despreciando el acarreo final. Simplifica la circuitería del procesador."},
{t:2,q:"4 + (−7) en C2 de 4 bits da…",o:["`1101` (−3)","`0011` (3)","`1011` (−5)","Desbordamiento"],a:0,e:"0100 + 1001 = 1101. Negativo; su C2 es 0011 = 3 → −3. Nunca hay desbordamiento con sumandos de distinto signo."},
{t:2,q:"Con 8 bits en C2, ¿cuándo hay desbordamiento (overflow) en una suma?",o:["Cuando los dos sumandos tienen el mismo signo y el resultado sale de signo contrario","Siempre que hay acarreo final","Cuando los sumandos tienen distinto signo","Cuando el resultado es 0"],a:0,e:"Ej.: 62 + 100 = 162 no cabe: 00111110 + 01100100 = 10100010 (−94).",w:{1:"El acarreo final se desprecia en C2; no indica overflow por sí solo."}},
{t:2,q:"Al extender −8 (`11111000`) de 8 a 16 bits en C2 se obtiene…",o:["`11111111 11111000`","`00000000 11111000`","`10000000 00001000`","`11111000 00000000`"],a:0,e:"Extensión de signo: se replica el bit de signo hacia la izquierda."},
{t:2,q:"+7 en representación sesgada de 8 bits (S = 128) es…",o:["`10000111`","`00000111`","`01111000`","`11111001`"],a:0,e:"Se guarda 7 + 128 = 135 = 10000111. Para decodificar: valor = binario − S."},
{t:2,q:"Con 4 bits, la sesgada con S = 8 coincide con el C2…",o:["Con el primer bit invertido","Exactamente","Con todos los bits invertidos","Sumándole 1"],a:0,e:"Ej.: 0 → 1000 en sesgada y 0000 en C2; −1 → 0111 y 1111."},
{t:2,q:"`010001101100,110100)2` en octal es…",o:["2154,64","46C,D","2154,32","1154,64"],a:0,e:"Grupos de 3 desde la coma: 010 001 101 100 , 110 100 → 2 1 5 4 , 6 4. (46C,D es el hexadecimal.)"},
{t:2,q:"`2E74,1C)16` en binario es…",o:["`0010 1110 0111 0100 , 0001 1100`","`010 110 111 100 , 001 100`","`0010 1110 0111 0100 , 1100 0001`","`1110 0010 0100 0111 , 0001 1100`"],a:0,e:"Cada dígito hexadecimal da exactamente 4 bits."},
{t:2,q:"760 decimal en hexadecimal es…",o:["2F8","1370","2E8","F28"],a:0,e:"760/16 = 47 resto 8; 47/16 = 2 resto 15 = F. Comprobación: 2·256 + 15·16 + 8 = 760. (1370 es el octal.)"},
{t:2,q:"En IEEE 754 de simple precisión los campos ocupan…",o:["1 bit de signo, 8 de exponente y 23 de mantisa","1, 11 y 52","1, 7 y 24","8, 1 y 23"],a:0,e:"32 bits en total, sesgo S = 127. Doble precisión: 1 + 11 + 52, S = 1023."},
{t:2,q:"El sesgo del exponente en IEEE 754 de doble precisión es…",o:["1023","127","1024","2047"],a:0,e:"S = 2^(ne−1) − 1 = 2^10 − 1 = 1023."},
{t:2,q:"Sobre el 1 de la mantisa normalizada en IEEE 754…",o:["No se almacena: es implícito (bit oculto)","Se almacena siempre en el bit 22","Se guarda en el campo de signo","Sólo se guarda en doble precisión"],a:0,e:"El número se normaliza como 1,m × 2^E; el procesador añade el 1 al leer (M = 1,m). En los desnormalizados M = 0,m."},
{t:2,q:"¿Qué número representa `C0580000)16` en IEEE 754 simple?",o:["−3,375","3,375","−1,6875","−6,75"],a:0,e:"1 | 10000000 | 1011000… → s = 1, E = 128 − 127 = 1, M = 1,1011 → −11,011)2 = −3,375."},
{t:2,q:"−250,875 en IEEE 754 de simple precisión es…",o:["`C37AE000`","`437AE000`","`C37AE00`","`C2FAE000`"],a:0,e:"11111010,111 = 1,1111010111 × 2^7; e = 134 = 10000110; s = 1 → 1100 0011 0111 1010 1110 0000… = C37AE000.",w:{1:"Le falta el signo: ése es +250,875."}},
{t:2,q:"0,75 en IEEE 754 simple es…",o:["`3F400000`","`3F000000`","`BF400000`","`40400000`"],a:0,e:"0,11)2 = 1,1 × 2^−1 → e = 126 = 01111110, m = 100… → 0 01111110 100… = 3F400000."},
{t:2,q:"`42C80000)16` en IEEE 754 simple representa…",o:["100","50","200","−100"],a:0,e:"0 | 10000101 | 1001000… → E = 133 − 127 = 6, 1,1001 × 2^6 = 1100100)2 = 100."},
{t:2,q:"En IEEE 754 simple, un exponente e = 255 con mantisa m = 0 representa…",o:["±∞ según el signo","NaN","El cero","Un número desnormalizado"],a:0,e:"e = 255 y m ≠ 0 → NaN; e = 0 y m = 0 → ±0; e = 0 y m ≠ 0 → desnormalizado."},
{t:2,q:"Un número desnormalizado en IEEE 754 simple (e = 0, m ≠ 0) vale…",o:["±0,m × 2^−126","±1,m × 2^−127","±1,m × 2^−126","±0,m × 2^−127"],a:0,e:"No tiene 1 implícito y el exponente es −126. Permite el desbordamiento gradual hacia 0."},
{t:2,q:"Con redondeo al par, mantisa `1,01101` y bits de redondeo/retenedor `10` (empate) se obtiene…",o:["`1,01110`","`1,01101`","`1,01100`","`1,01111`"],a:0,e:"Empate: se redondea al que termina en par. 1,01101 acaba en 1 (impar) → se suma 1."},
{t:2,q:"¿Por qué en IEEE 754 puede fallar la asociatividad de la suma?",o:["Porque los resultados intermedios se redondean a un número finito de bits","Porque la suma en coma flotante no es conmutativa","Porque el exponente se guarda en C2","Porque se usa little endian"],a:0,e:"Con a = 1, b = −1, c = 2^−30: (a + b) + c = 2^−30 pero a + (b + c) = 0, porque b + c se redondea a −1."},
{t:2,q:"Un mayor número de bits de exponente en coma flotante da…",o:["Más rango","Más precisión","Menos rango","Lo mismo, sólo importa la mantisa"],a:0,e:"Más bits de mantisa → más precisión (cifras significativas); más bits de exponente → más rango."},
{t:2,q:"ASCII codifica sus caracteres con…",o:["7 bits (128 caracteres)","8 bits (256 caracteres)","16 bits","Entre 1 y 4 bytes"],a:0,e:"El octavo bit del byte se usa para paridad, gráficos o, sobre todo, extensiones de idioma (ISO 8859-1, 8859-15)."},
{t:2,q:"¿Qué código ASCII tiene la letra «a»?",o:["97 (0x61)","65 (0x41)","48 (0x30)","122 (0x7A)"],a:0,e:"Minúscula = mayúscula + 32: «A» = 65, «a» = 97. Los dígitos empiezan en 48."},
{t:2,q:"El carácter «7» en ASCII vale…",o:["55","7","48","0x07"],a:0,e:"El carácter de un dígito d vale 48 + d. El carácter «7» no es el número 7.",w:{1:"Ése es el número 7, no el carácter."}},
{t:2,q:"Con paridad par, el carácter «C» (`1000011`) se guarda como…",o:["`11000011`","`01000011`","`10000110`","`11000010`"],a:0,e:"Tiene 3 unos (impar), así que el bit de paridad es 1 para que el total sea par."},
{t:2,q:"Sobre el bit de paridad es cierto que…",o:["Detecta errores en un número impar de bits, pero no los corrige","Detecta y corrige cualquier error","Detecta siempre dos bits cambiados","Indica qué bit ha fallado"],a:0,e:"Si cambian dos bits la paridad no cambia y el error pasa inadvertido."},
{t:2,q:"¿Cuántos bits hacen falta como mínimo para codificar 10 caracteres distintos?",o:["4","3","10","5"],a:0,e:"n ≥ log2 m: 2^3 = 8 < 10 ≤ 16 = 2^4."},
{t:2,q:"Sobre UTF-8 es cierto que…",o:["Usa 1 byte para los caracteres ASCII y de 2 a 4 para el resto","Usa siempre 2 bytes por carácter","Usa siempre 4 bytes por carácter","No es compatible con ASCII"],a:0,e:"Es compatible con ASCII y el más usado. UTF-16 usa unidades de 2 bytes.",w:{1:"Falso: va de 1 a 4 bytes."}},
{t:2,q:"La «ñ» (U+00F1) en UTF-8 es…",o:["`C3 B1`","`F1`","`00 F1`","`E2 82 AC`"],a:0,e:"11 bits → 110yyyyy 10xxxxxx = 11000011 10110001. En ISO 8859-1 sería el byte F1. E2 82 AC es el €."},
{t:2,q:"¿Cuántos bytes ocupa el símbolo € (U+20AC) en UTF-8?",o:["3","1","2","4"],a:0,e:"Está entre U+0800 y U+FFFF → 1110zzzz 10yyyyyy 10xxxxxx = E2 82 AC."},
{t:2,q:"El BOM (Byte Order Mark) de UTF-16 sirve para…",o:["Indicar si el texto está en big endian (FE FF) o little endian (FF FE)","Marcar el final del texto","Comprimir el texto","Detectar errores de paridad"],a:0,e:"UTF-16 usa unidades de 16 bits, así que importa el orden de los bytes."},
{t:2,q:"¿Cuánto ocupa sin comprimir una imagen RGB de 1920 × 1080 con 8 bits por color?",o:["6 220 800 bytes (≈ 5,93 MB)","2 073 600 bytes","24 883 200 bytes","518 400 bytes"],a:0,e:"Píxeles × bytes por píxel = 1920 · 1080 · 3. En escala de grises sería un byte por píxel."},
{t:2,q:"El modelo de color RGB es…",o:["Aditivo (la suma de los tres da blanco), usado en pantallas","Sustractivo, usado en impresión","De escala de grises","Un formato de mapa de vectores"],a:0,e:"CMYK (cian, magenta, amarillo, negro) es el sustractivo, usado en impresión con tinta."},
{t:2,q:"Frente a los mapas de bits, los mapas de vectores…",o:["Ocupan menos y se escalan sin perder calidad, pero no sirven para fotos","Son mejores para fotografías reales","Guardan el color de cada píxel","Siempre usan compresión con pérdida"],a:0,e:"Modelan objetos (líneas, polígonos, textos) con ecuaciones: ideales para CAD. Formatos: DXF, EPS, ODG."},
{t:2,q:"¿Cuál de estos formatos es de mapa de bits?",o:["PPM","DXF","EPS","ODG"],a:0,e:"Mapa de bits: BMP, PICT, PPM, JPEG. Vectoriales: DXF, EPS, ODG."},
{t:2,q:"La compresión con pérdida…",o:["Elimina información que el ojo apenas percibe para ocupar menos","Permite recuperar la imagen exactamente","No se usa en JPEG","Sólo existe en mapas de vectores"],a:0,e:"La sin pérdida recupera la imagen exacta. (En una transparencia aparece al revés: es una errata.)"},
/* ---------------- TEMA 3 · Circuitos combinacionales ---------------- */
{t:3,q:"Un circuito combinacional es aquel cuyas salidas…",o:["Dependen sólo de las entradas actuales","Dependen de las entradas y del estado almacenado","Cambian sólo con el flanco del reloj","Se guardan en registros"],a:0,e:"Combinacional = sin memoria (MUX, decodificador, sumador, ROM). Secuencial = con memoria (banco de registros), se ve en ETC."},
{t:3,q:"¿Cuál de estos circuitos es SECUENCIAL?",o:["Un banco de registros","Un multiplexor","Un decodificador","Una memoria ROM"],a:0,e:"La ROM, pese a llamarse memoria, es combinacional: su salida depende sólo de la dirección de entrada.",w:{3:"Trampa típica: la ROM es combinacional."}},
{t:3,q:"Una función lógica de n variables tiene una tabla de verdad de…",o:["2^n filas","n filas","n² filas","2n filas"],a:0,e:"Cada fila es una combinación de las n entradas: 2^n combinaciones."},
{t:3,q:"Según la ley de absorción, `A + A·B` es igual a…",o:["`A`","`B`","`A·B`","`1`"],a:0,e:"A + A·B = A·(1 + B) = A·1 = A. Su dual: A·(A + B) = A."},
{t:3,q:"La forma distributiva que NO existe en el álgebra ordinaria es…",o:["`A + B·C = (A + B)·(A + C)`","`A·(B + C) = A·B + A·C`","`A + 0 = A`","`A·1 = A`"],a:0,e:"En el álgebra de Boole la suma también distribuye sobre el producto."},
{t:3,q:"Según De Morgan, el complemento de `A·B` es…",o:["`A' + B'`","`A'·B'`","`A + B`","`(A + B)'`"],a:0,e:"El complemento de un producto es la suma de los complementos (y el de una suma, el producto de los complementos)."},
{t:3,q:"Un minitérmino m_i es…",o:["Un producto con todas las variables que vale 1 sólo en la fila i","Una suma con todas las variables que vale 0 sólo en la fila i","Un producto de dos variables cualquiera","La salida de un multiplexor"],a:0,e:"La suma de los minitérminos de las filas con F = 1 da la forma canónica Σm. El maxitérmino M_i es la suma que vale 0 sólo en la fila i."},
{t:3,q:"En un maxitérmino, una variable aparece negada cuando en esa fila vale…",o:["1","0","Indiferente","Siempre aparece sin negar"],a:0,e:"Así la suma vale 0 justo en esa fila. En los minitérminos es al revés: negada si vale 0."},
{t:3,q:"Si F = Σm(2, 3, 6, 7) con variables A, B, C, entonces en forma de maxitérminos F = …",o:["ΠM(0, 1, 4, 5)","ΠM(2, 3, 6, 7)","ΠM(0, 1, 2, 3)","ΠM(4, 5, 6, 7)"],a:0,e:"Los índices de minitérminos y maxitérminos son complementarios: entre los dos cubren 0…7."},
{t:3,q:"F(A,B,C) = Σm(2, 3, 6, 7) simplificada es…",o:["`B`","`A`","`A·B`","`B + C`"],a:0,e:"Son las filas con B = 1: F = A'B(C' + C) + AB(C' + C) = A'B + AB = B."},
{t:3,q:"En un mapa de Karnaugh, las filas y columnas se ordenan en código Gray (00, 01, 11, 10) para que…",o:["Entre celdas vecinas sólo cambie un bit","Las celdas queden en orden numérico","Haya menos celdas","Las indiferencias queden juntas"],a:0,e:"Así minitérminos adyacentes ocupan celdas adyacentes (incluidos los bordes, que también son vecinos)."},
{t:3,q:"Al agrupar 8 celdas en un mapa de Karnaugh de 4 variables se eliminan…",o:["3 variables","8 variables","2 variables","4 variables"],a:0,e:"Un grupo de 2^k celdas elimina k variables: 8 = 2^3 → el término tiene una sola variable."},
{t:3,q:"En un mapa de Karnaugh, ¿qué tamaños de grupo son válidos?",o:["Rectángulos de 1, 2, 4, 8 o 16 celdas","Cualquier número de celdas contiguas","Sólo parejas","Grupos de 3 o de 6 celdas"],a:0,e:"Siempre potencias de 2 y en forma de rectángulo (puede usar la adyacencia de los bordes)."},
{t:3,q:"Un implicante primo esencial es…",o:["Un implicante primo que cubre al menos un 1 que ningún otro primo cubre","Cualquier grupo de unos","El grupo más grande del mapa","Un implicante contenido en otro mayor"],a:0,e:"Siempre forma parte de la solución mínima. Un implicante primo es el que no está contenido en otro mayor.",w:{3:"Eso es justo lo contrario de primo."}},
{t:3,q:"Simplificando por ceros en un mapa de Karnaugh se obtiene…",o:["Un producto de sumas","Una suma de productos","Una función sin variables negadas","La forma canónica Σm"],a:0,e:"En cada grupo de ceros las variables que no cambian aparecen negadas si valen 1, sumadas; los grupos se multiplican."},
{t:3,q:"Las indiferencias (X) de un mapa de Karnaugh…",o:["Pueden tomarse como 1 o 0 según convenga, y no es obligatorio cubrirlas","Hay que cubrirlas siempre","Siempre valen 0","Siempre valen 1"],a:0,e:"Representan entradas que no pueden darse (p. ej. 1010–1111 si la entrada es un dígito BCD)."},
{t:3,q:"Una puerta XOR de dos entradas vale 1 cuando…",o:["Las entradas son distintas","Las entradas son iguales","Todas las entradas son 1","Todas las entradas son 0"],a:0,e:"A ⊕ B = A'B + AB' (nº impar de unos). La XNOR vale 1 cuando son iguales."},
{t:3,q:"Una puerta NOR vale 1 cuando…",o:["Todas las entradas son 0","Alguna entrada es 0","Alguna entrada es 1","Todas las entradas son 1"],a:0,e:"NOR = OR negada: tabla 1 0 0 0. La NAND vale 1 cuando alguna entrada es 0."},
{t:3,q:"¿Qué puertas son universales (con ellas solas se implementa cualquier función)?",o:["NAND y NOR","AND y OR","XOR y XNOR","NOT y AND por separado"],a:0,e:"Con NAND: NOT A = NAND(A, A); AND = NAND seguida de NAND‑inversor; OR = NAND de las entradas negadas."},
{t:3,q:"¿Cómo se obtiene NOT A usando sólo una puerta NAND?",o:["Uniendo sus dos entradas a A","Poniendo una entrada a 0","Con dos NAND en serie","No se puede"],a:0,e:"NAND(A, A) = (A·A)' = A'. Con NOR igual: NOR(A, A) = A'."},
{t:3,q:"Para implementar una función sólo con NAND se parte de…",o:["La suma de productos (simplificación por unos)","El producto de sumas","La tabla de maxitérminos","Un multiplexor"],a:0,e:"Doble negación + De Morgan → estructura NAND‑NAND. Con NOR se parte del producto de sumas (estructura NOR‑NOR)."},
{t:3,q:"Retardos: NOT 5 ns, AND 10 ns, OR 10 ns. El camino más lento es NOT → AND → OR. ¿Retardo del circuito?",o:["25 ns","30 ns","10 ns","35 ns"],a:0,e:"El retardo total es el del camino crítico: 5 + 10 + 10. Las puertas que trabajan en paralelo no suman."},
{t:3,q:"El retardo total de un circuito combinacional es…",o:["El del camino más lento desde una entrada hasta la salida","La suma de los retardos de todas sus puertas","El retardo de la última puerta","El de la puerta más rápida"],a:0,e:"En cada puerta, su salida está lista en (instante de la entrada más tardía) + (retardo de la puerta)."},
{t:3,q:"Un chip con entre 100 y 100 000 puertas es de escala de integración…",o:["LSI","SSI","MSI","VLSI"],a:0,e:"SSI 1–10, MSI 10–100, LSI 100–100 000, VLSI más de 100 000."},
{t:3,q:"Un decodificador de n entradas tiene…",o:["2^n salidas y activa una y sólo una","n salidas y activa todas","2^n entradas y n salidas","una sola salida"],a:0,e:"Cada salida es un minitérmino: es un generador de minitérminos. Se usa para direccionar memoria.",w:{2:"Eso es un codificador."}},
{t:3,q:"Para implementar F(A,B,C,D) = Σm(2, 3, 4, 5, 7, 8, 10, 13, 15) con un decodificador se usa…",o:["Un decodificador 4 a 16 y una OR con las salidas 2, 3, 4, 5, 7, 8, 10, 13 y 15","Un decodificador 2 a 4 y una AND","Un decodificador 4 a 16 y una AND con las salidas que valen 0","Un codificador 16 a 4"],a:0,e:"Cada salida del decodificador es un minitérmino y la OR los suma: es la forma canónica."},
{t:3,q:"En un codificador 8 a 3 se activa la entrada E5. La salida S2 S1 S0 es…",o:["`101`","`011`","`110`","`00100000`"],a:0,e:"El codificador da en binario el número de la entrada activada: 5 = 101."},
{t:3,q:"Un multiplexor de 2^n entradas de datos tiene…",o:["n entradas de control y una salida","2^n entradas de control","n salidas","2^n salidas"],a:0,e:"Es un selector: las líneas de control eligen qué entrada pasa a la salida. MUX 4 a 1: 2 de control."},
{t:3,q:"La salida de un MUX 2 a 1 con control C es…",o:["`F = C'·I0 + C·I1`","`F = C·I0 + C'·I1`","`F = I0·I1`","`F = C ⊕ I0`"],a:0,e:"Con C = 0 pasa I0 y con C = 1 pasa I1."},
{t:3,q:"Para implementar una función de 4 variables con un MUX 8 a 1 (A, B, C al control), cada entrada de datos puede ser…",o:["0, 1, D o D'","Sólo 0 o 1","A, B o C","Cualquier minitérmino"],a:0,e:"Cada entrada cubre dos filas (D = 0 y D = 1): (0,0) → 0; (1,1) → 1; (0,1) → D; (1,0) → D'."},
{t:3,q:"¿Cómo se construye un MUX 2×1 de 32 bits?",o:["Con 32 MUX 2×1 de 1 bit que comparten la señal de control","Con un MUX 64 a 1","Con 5 MUX en cascada","Con un decodificador 5 a 32"],a:0,e:"Cada MUX elige el bit i de A o de B con la misma señal de control."},
{t:3,q:"Una ROM con 3 entradas de dirección y 4 salidas tiene forma…",o:["8 × 4","3 × 4","4 × 8","16 × 3"],a:0,e:"m entradas → 2^m posiciones (altura); n salidas → anchura. 2^3 × 4 = 8 × 4."},
{t:3,q:"Una ROM de 2^m × n puede implementar…",o:["n funciones distintas de las mismas m variables","m funciones de n variables","Una sola función","2^m funciones"],a:0,e:"Cada columna de salida es una función. Plano AND = decodificador (todos los minitérminos), plano OR con n puertas."},
{t:3,q:"¿Qué variante de ROM se borra con luz ultravioleta?",o:["EPROM","EEPROM","PROM","Flash"],a:0,e:"PROM: programable una vez. EEPROM: borrable eléctricamente. Flash: borrado por bloques (pendrives, SSD, BIOS)."},
{t:3,q:"La diferencia de una PLA frente a una ROM es que…",o:["En el plano AND sólo implementa los productos necesarios","No tiene plano OR","Es un circuito secuencial","Tiene todos los minitérminos"],a:0,e:"Ambos planos son programables. Su forma se da como entradas × productos × salidas (p. ej. 3 × 6 × 4)."},
{t:3,q:"En un semisumador de 1 bit, el resultado y el acarreo de salida son…",o:["R = A XOR B y C = A AND B","R = A OR B y C = A AND B","R = A AND B y C = A XOR B","R = A XNOR B y C = A OR B"],a:0,e:"El resultado es 1 cuando sólo una entrada vale 1; el acarreo, sólo cuando las dos valen 1. No tiene en cuenta el acarreo de entrada."},
{t:3,q:"El acarreo de salida de un sumador completo de 1 bit, simplificado, es…",o:["`Ci+1 = A·B + A·Ci + B·Ci`","`Ci+1 = A ⊕ B ⊕ Ci`","`Ci+1 = A·B·Ci`","`Ci+1 = A + B + Ci`"],a:0,e:"Vale 1 cuando al menos dos de las tres entradas son 1. El bit de resultado es R = A ⊕ B ⊕ Ci.",w:{1:"Ése es el bit de resultado R."}},
{t:3,q:"El principal inconveniente del sumador serie (con propagación de acarreo) de n bits es…",o:["Que los retardos de los n sumadores se acumulan","Que no puede restar","Que necesita un decodificador","Que sólo suma números pares"],a:0,e:"Cada bit espera al acarreo del anterior. Los procesadores reales usan sumadores con acarreo adelantado (carry lookahead)."},
{t:3,q:"¿Por qué un sumador binario sirve también para restar?",o:["Porque sumando en C2 el resultado también es correcto en C2","Porque la resta es una XOR","Porque se invierte el acarreo","No sirve para restar"],a:0,e:"A − B = A + C2(B): basta invertir B y meter un 1 por el acarreo de entrada."},
/* ---------------- TEMA 4 · Sistemas operativos (Linux) ---------------- */
{t:4,q:"El sistema operativo es…",o:["La capa de software inmediatamente por encima del hardware que administra CPU, memoria y dispositivos","Un programa de aplicación como el navegador","El firmware de la placa base","El compilador de C"],a:0,e:"Comparte la CPU y la memoria entre procesos (protegiéndolos) y ofrece una interfaz uniforme a dispositivos muy distintos."},
{t:4,q:"Las dos visiones complementarias del SO son…",o:["Máquina extendida (virtual) y administrador de recursos","Núcleo y distribución","Modo usuario y modo núcleo","Cliente y servidor"],a:0,e:"Máquina extendida: oculta la complejidad del hardware (programas de sistema, llamadas al sistema). Administrador: reparte los recursos de forma eficiente y segura."},
{t:4,q:"¿Qué es una distribución de Linux?",o:["Núcleo + software adicional + sistema de configuración","Sólo el núcleo de Linux","Un sistema de ficheros","Un intérprete de comandos"],a:0,e:"Ubuntu, Fedora, Debian, SUSE… El núcleo (kernel) es el SO propiamente dicho."},
{t:4,q:"¿Qué diferencia hay entre programa y proceso?",o:["El programa es código ejecutable en disco (estático); el proceso, un programa en ejecución (dinámico)","Son lo mismo","El proceso está en disco y el programa en memoria","El programa sólo existe en Linux"],a:0,e:"El proceso tiene estado (contador de programa, datos…) y necesita recursos. Un mismo programa puede dar lugar a varios procesos a la vez.",w:{2:"Al revés."}},
{t:4,q:"La unidad de trabajo del sistema operativo es…",o:["El proceso","El fichero","El usuario","La sesión"],a:0,e:"El SO debe crear, eliminar, suspender, reanudar, comunicar y sincronizar procesos."},
{t:4,q:"Un sistema operativo que debe responder en un tiempo máximo garantizado (robots, control industrial) es de tipo…",o:["Tiempo real","Propósito general","Tarjeta inteligente","Servidor"],a:0,e:"Otros tipos: propósito general, servidores, integrados (móviles), tarjeta inteligente, supercomputadores."},
{t:4,q:"Sobre Linux es cierto que…",o:["Es un clon de Unix iniciado por Linus Torvalds en 1991 con licencia GPL","Es software propietario de Microsoft","Sólo funciona en procesadores Intel","Es monousuario"],a:0,e:"Multiplataforma, multiusuario, multitarea y escrito casi íntegramente en C. Su sistema de ficheros nativo es Ext4."},
{t:4,q:"El único usuario con acceso total al sistema en Linux es…",o:["root","admin","alumno","sudo"],a:0,e:"El superusuario. Los demás usuarios no pueden, por ejemplo, modificar /etc/group."},
{t:4,q:"En el prompt `pedroe@funes:~/docs$`, «funes» es…",o:["El nombre de la máquina","El usuario","El directorio actual","El intérprete de comandos"],a:0,e:"usuario@máquina:directorio_actual$."},
{t:4,q:"¿Qué orden muestra el directorio de trabajo actual?",o:["`pwd`","`cd`","`whoami`","`ls -d`"],a:0,e:"cd cambia de directorio; whoami dice qué usuario eres."},
{t:4,q:"¿Qué hace `cd -`?",o:["Vuelve al directorio anterior","Va al directorio raíz","Va al directorio padre","Va al home del usuario"],a:0,e:"cd ~ (o cd sin argumentos) va al home; cd .. al padre; cd / a la raíz."},
{t:4,q:"La ayuda de un comando EXTERNO se consulta con…",o:["`man comando`","`help comando`","`history comando`","`info -i comando`"],a:0,e:"help es para las órdenes internas de bash. Dentro de man se busca con /palabra y se sale con q.",w:{1:"help es para comandos internos de bash."}},
{t:4,q:"`!ls` en bash…",o:["Vuelve a ejecutar la última orden que empezaba por «ls»","Niega la orden ls","Ejecuta ls como root","Muestra la ayuda de ls"],a:0,e:"También: flechas para recorrer el historial, history para listarlo y Ctrl-R para buscar."},
{t:4,q:"¿Qué hay en el directorio /etc?",o:["Ficheros de configuración","Los datos de los usuarios","Los dispositivos","Ficheros temporales"],a:0,e:"/home = datos de usuarios; /dev = dispositivos; /tmp = temporales; /bin y /usr/bin = programas; /proc = estructuras internas del SO."},
{t:4,q:"Sobre /proc es cierto que…",o:["No está en disco: lo mantiene el núcleo en tiempo real","Contiene los programas de usuario","Es un directorio vacío","Guarda las copias de seguridad"],a:0,e:"Tiene un subdirectorio por PID y ficheros como /proc/cpuinfo, /proc/meminfo o /proc/version."},
{t:4,q:"Estando en /home/juan/progs, la ruta relativa a /home/juan/docs/fich.txt es…",o:["`../docs/fich.txt`","`./docs/fich.txt`","`/docs/fich.txt`","`~/progs/docs/fich.txt`"],a:0,e:".. sube al directorio padre (/home/juan) y desde ahí se baja a docs. Una ruta que empieza por / es absoluta."},
{t:4,q:"En `ls -l`, la línea `drwxr-xr-x 3 pedroe pedroe 4096 jun 12 14:12 fig` indica que fig es…",o:["Un directorio","Un fichero regular","Un enlace simbólico","Un dispositivo"],a:0,e:"El primer carácter es el tipo: - fichero regular, d directorio, l enlace simbólico."},
{t:4,q:"¿Qué opción de ls muestra también los ficheros ocultos?",o:["`-a`","`-l`","`-R`","`-d`"],a:0,e:"Los ocultos empiezan por punto (.bashrc). -R es recursivo; -d lista el directorio en sí, no su contenido."},
{t:4,q:"El comodín `?` significa…",o:["Exactamente un carácter cualquiera","Cero o más caracteres","Un carácter que no está en el rango","Cualquier cadena de la lista"],a:0,e:"* = 0 o más caracteres; [a-z] = uno del rango; [!b-d] = uno que no esté en el rango; {a,b} = cualquiera de las cadenas."},
{t:4,q:"¿Qué orden lista los ficheros de /usr/bin cuyo nombre tiene exactamente 4 caracteres?",o:["`ls /usr/bin/????`","`ls /usr/bin/*4`","`ls /usr/bin/[4]`","`ls -4 /usr/bin`"],a:0,e:"Cada ? es exactamente un carácter. Los comodines los expande el propio bash."},
{t:4,q:"`*.[!c]` encaja con…",o:["Ficheros con extensión de un carácter distinto de c","Ficheros que no acaban en .c de cualquier longitud","Todos los ficheros .c","Ficheros sin extensión"],a:0,e:"pepe.h o f1.a sí; antonio.c no; «fichero» (sin punto) tampoco."},
{t:4,q:"`find dir -type f -iname \"*.tgz\"` busca…",o:["Ficheros regulares con extensión .tgz sin distinguir mayúsculas","Directorios llamados .tgz","Sólo ficheros .tgz en minúsculas","Ficheros de más de 1 KB"],a:0,e:"-iname ignora mayúsculas (.TGZ, .Tgz…). find busca recursivamente en dir y sus subdirectorios."},
{t:4,q:"`find dir -size +140k -o -mtime -100` muestra entradas…",o:["De más de 140 KB o modificadas hace menos de 100 días","De más de 140 KB y modificadas hace más de 100 días","De menos de 140 KB","Modificadas exactamente hace 100 días"],a:0,e:"-o es el O lógico (el Y es implícito). +n = más de, −n = menos de."},
{t:4,q:"¿Qué orden borra un directorio que NO está vacío con todo su contenido?",o:["`rm -r dir`","`rmdir dir`","`rm dir`","`mv dir /dev/null`"],a:0,e:"rmdir sólo borra directorios vacíos. rm sin -r no borra directorios.",w:{1:"rmdir sólo borra directorios vacíos."}},
{t:4,q:"`touch fichero` sobre un fichero que ya existe…",o:["Actualiza su fecha de modificación a la actual","Lo borra","Lo vacía","Da error"],a:0,e:"Si no existe, lo crea vacío."},
{t:4,q:"¿Qué hace `tar czvf res.tgz docs`?",o:["Empaqueta y comprime docs en res.tgz","Extrae res.tgz en docs","Lista el contenido de res.tgz","Copia docs en res.tgz sin comprimir"],a:0,e:"c = crear, z = comprimir con gzip, v = verbose, f = fichero. t lista y x extrae."},
{t:4,q:"`chmod 754 fich` deja los permisos…",o:["`rwxr-xr--`","`rwxrw-r--`","`rw-r-xr--`","`rwxr-xr-x`"],a:0,e:"Cada cifra octal son 3 bits rwx (r = 4, w = 2, x = 1): 7 = rwx, 5 = r-x, 4 = r--."},
{t:4,q:"Los permisos típicos de un fichero de texto (rw-r--r--) en octal son…",o:["644","755","600","744"],a:0,e:"6 = rw-, 4 = r--. 755 es típico de directorios y ejecutables; 600, de un fichero privado."},
{t:4,q:"En un directorio, el permiso x permite…",o:["Acceder a su contenido (entrar con cd, recorrerlo)","Ejecutar el directorio como un programa","Listar su contenido","Crear ficheros dentro"],a:0,e:"r = listarlo (ls); w = crear y borrar ficheros dentro; x = entrar (cd) y recorrerlo (find)."},
{t:4,q:"Si a un directorio le pones permisos 600 y haces cd a él…",o:["Falla con «Permiso denegado», porque no tiene x","Entras sin problema","Se borra el directorio","Cambia de propietario"],a:0,e:"Sin el permiso x no se puede acceder al directorio aunque tengas r y w."},
{t:4,q:"`/dev/sda2` representa…",o:["La segunda partición del primer disco","El segundo disco","El dispositivo de red","La memoria RAM"],a:0,e:"sd = discos (y USB); a, b, c = unidades; 1, 2, 3 = particiones."},
{t:4,q:"¿Qué orden muestra lo que ocupa realmente en disco un directorio y todo lo que cuelga de él?",o:["`du -hs dir`","`df dir`","`ls -l dir`","`free dir`"],a:0,e:"df muestra el espacio total, usado y libre de los sistemas de ficheros montados."},
{t:4,q:"`ls -l` y `du -h` dan tamaños distintos para un fichero pequeño porque…",o:["ls muestra el tamaño real en bytes y du los bloques que ocupa en disco (p. ej. 4 KiB)","du no funciona con ficheros","ls redondea al KB","el fichero está comprimido"],a:0,e:"Los ficheros se guardan en bloques de tamaño fijo, normalmente de 4 KiB."},
{t:4,q:"`kcalc ; kate ;` lanza los programas…",o:["En primer plano, uno tras otro: kate no arranca hasta que se cierra kcalc","En segundo plano y a la vez","Sólo kate","En segundo plano, uno tras otro"],a:0,e:"Con & se lanzan en segundo plano: no se esperan y el prompt vuelve en seguida."},
{t:4,q:"¿Qué hace Ctrl-Z sobre el proceso en primer plano?",o:["Lo duerme (suspende); se reanuda con fg o bg","Lo mata","Lo pasa a segundo plano directamente","Cierra el terminal"],a:0,e:"Ctrl-C lo mata. fg lo reanuda en primer plano y bg en segundo."},
{t:4,q:"`kill -9 PID`…",o:["Termina forzosamente el proceso; la señal no se puede capturar","Duerme el proceso","Muestra el proceso PID","Reinicia el proceso"],a:0,e:"kill sin -9 envía una señal de terminación que el proceso sí puede capturar."},
{t:4,q:"En la salida de `ps -Af`, la columna PPID es…",o:["El PID del proceso padre","El tiempo de CPU","El terminal","La prioridad"],a:0,e:"UID (usuario), PID, PPID (padre), STIME (hora de inicio), TTY (terminal), TIME (tiempo de CPU), CMD."},
{t:4,q:"¿Qué hace `ls -l >> fich.txt`?",o:["Añade la salida estándar al final de fich.txt","Sobrescribe fich.txt","Redirige los errores a fich.txt","Lee la entrada de fich.txt"],a:0,e:"> sobrescribe («machaca»); 2> redirige stderr; < redirige stdin; | conecta procesos (tubería)."},
{t:4,q:"Para guardar sólo los mensajes de ERROR de una orden en err.txt se usa…",o:["`orden 2> err.txt`","`orden > err.txt`","`orden < err.txt`","`orden | err.txt`"],a:0,e:"El descriptor 2 es la salida de error estándar (stderr)."},
{t:4,q:"En `ls -l | grep \".c\" | wc -l`, el símbolo `|`…",o:["Conecta la salida de cada orden con la entrada de la siguiente (tubería)","Lanza las órdenes en segundo plano","Es un O lógico","Redirige a un fichero"],a:0,e:"Es una tubería: comunicación entre procesos."},
{t:4,q:"Al copiar /bin/ls a ~/myls, para ejecutarlo hay que escribir `./myls` porque…",o:["El directorio home no está en el PATH","myls no tiene permisos de lectura","Es un fichero oculto","ls es una orden interna"],a:0,e:"El shell sólo busca los ejecutables en los directorios de la variable PATH (echo $PATH)."},
{t:4,q:"El cambio de contexto ocurre cuando…",o:["El reloj interrumpe al proceso actual y el kernel continúa con otro","Se cambia de usuario","Se monta un disco","Se compila un programa"],a:0,e:"El tiempo que se deja a cada proceso es su quantum; quien elige el siguiente es el planificador (scheduler)."},
{t:4,q:"La parte del núcleo que decide qué proceso se ejecuta es…",o:["El planificador (scheduler)","El cargador","El manejador de dispositivo","La MMU"],a:0,e:"Es el responsable de optimizar el uso de la CPU en la multiprogramación."},
{t:4,q:"En Linux, el proceso raíz del que descienden todos los demás es…",o:["systemd (PID 1)","bash","root","kernel (PID 0)"],a:0,e:"Antiguamente init. Todo proceso lo crea un proceso padre."},
{t:4,q:"La controladora de dispositivo es ___ y el manejador (driver) es ___.",o:["hardware · software que ejecuta el kernel en modo privilegiado","software · hardware","parte del disco · parte de la BIOS","un proceso de usuario · un fichero"],a:0,e:"La controladora es un chip que acepta comandos elementales en sus registros; el driver se comunica con ella."},
{t:4,q:"Ordena el arranque: (a) carga del núcleo, (b) systemd, (c) ROM BIOS y autodiagnóstico, (d) login.",o:["c → a → b → d","a → c → b → d","c → b → a → d","b → c → a → d"],a:0,e:"ROM BIOS + POST → cargador que deja residente el kernel → el kernel crea sus estructuras → systemd y demonios → procesos de login."},
{t:4,q:"Una llamada al sistema es…",o:["Una interrupción software: el proceso pide explícitamente un servicio al SO","Una interrupción del reloj","Un error de división por cero","Una señal de un periférico"],a:0,e:"En la clasificación de ETC: traps (syscall, int 80h). Excepciones = errores internos; interrupciones = eventos externos."},
{t:4,q:"Una división por cero genera…",o:["Una excepción","Una llamada al sistema","Una interrupción de reloj","Un cambio de usuario"],a:0,e:"Las excepciones (o desvíos) se generan dentro de la CPU por un error del proceso en ejecución."},
{t:4,q:"El núcleo se ejecuta en…",o:["Modo núcleo (privilegiado)","Modo usuario","La BIOS","El disco duro"],a:0,e:"Las aplicaciones y librerías van en modo usuario, con restricciones. Se pasa de uno a otro con llamadas al sistema e interrupciones."},
/* ---------------- TEMA 5 · Lenguajes: alto nivel, ensamblador y máquina ---------------- */
{t:5,q:"Un programa es…",o:["Un conjunto ordenado de instrucciones que el computador ejecuta sobre los datos","Una única orden de operación","Un fichero de datos","Un proceso en ejecución"],a:0,e:"Las instrucciones se ejecutan en secuencia; la secuencia sólo se rompe con saltos (bucles, if, llamadas)."},
{t:5,q:"Con un formato de instrucción de 6 bits de código de operación y dos campos de registro de 5 bits, ¿cuántos registros se pueden codificar?",o:["32","64","5","10"],a:0,e:"2^5 = 32 registros y 2^6 = 64 códigos de operación."},
{t:5,q:"El contador de programa (PC) contiene…",o:["La dirección de la instrucción a ejecutar","La instrucción que se está ejecutando","El resultado de la última operación","El número de instrucciones ejecutadas"],a:0,e:"La instrucción en ejecución está en el registro de instrucción (RI). En x86-64 el PC se llama RIP.",w:{1:"Eso es el registro de instrucción (RI)."}},
{t:5,q:"El ciclo de instrucción es…",o:["Leer la instrucción apuntada por el PC, decodificarla y actualizar el PC, ejecutarla y repetir","Compilar, ensamblar, enlazar y cargar","Leer el disco, cargar en RAM y ejecutar","Push, call, ret y pop"],a:0,e:"(1) leer en el RI, (2) decodificar y actualizar el PC, (3) leer operandos, ejecutar y escribir el resultado, (4) repetir."},
{t:5,q:"Sobre RISC y CISC es cierto que…",o:["RISC tiene pocas instrucciones sencillas, normalmente de longitud fija; x86 es CISC","x86 es RISC y MIPS es CISC","CISC tiene instrucciones de longitud fija","RISC tiene instrucciones de muchos ciclos"],a:0,e:"RISC: MIPS, ARM, RISC-V. CISC: Intel x86, instrucciones complejas de longitud variable."},
{t:5,q:"¿Qué herramienta transforma el código C en ensamblador?",o:["El compilador","El ensamblador","El enlazador","El cargador"],a:0,e:"Compilador → .s (texto); ensamblador → .o (binario); enlazador → ejecutable; cargador → lo pone en memoria."},
{t:5,q:"El enlazador (linker)…",o:["Une los ficheros objeto entre sí y con las librerías y genera el ejecutable","Traduce de C a ensamblador","Carga el ejecutable en memoria","Convierte el ensamblador en código objeto"],a:0,e:"Al unirlos resuelve las referencias cruzadas y fija las direcciones definitivas."},
{t:5,q:"El cargador (loader)…",o:["Es un módulo del SO que lee el ejecutable, lo ubica en memoria y le pasa el control","Es parte del compilador","Une los ficheros objeto","Comprime el ejecutable"],a:0,e:"Es parte del sistema operativo."},
{t:5,q:"¿Qué contiene un fichero objeto (.o)?",o:["Instrucciones máquina, datos en formato interno e información de reubicación","Sólo texto ASCII en ensamblador","El programa ya cargado en memoria","Sólo las funciones de librería"],a:0,e:"La información de reubicación permite al enlazador fijar las direcciones de accesos a memoria y saltos."},
{t:5,q:"¿Qué orden genera SÓLO el fichero en ensamblador main.s?",o:["`gcc -S main.c -o main.s`","`gcc -c main.c -o main.s`","`gcc main.c -o main.s`","`objdump -d main.c`"],a:0,e:"-S sólo compila; -c compila y ensambla (→ .o); sin opciones hace todo hasta el ejecutable.",w:{1:"-c genera el objeto .o."}},
{t:5,q:"¿Qué orden muestra desensamblado el código de un fichero objeto?",o:["`objdump -d main.o`","`gcc -S main.o`","`ldd main.o`","`hexdump main.c`"],a:0,e:"Muestra en columnas el desplazamiento, los bytes del código máquina y la instrucción en ensamblador."},
{t:5,q:"Con librerías dinámicas (.so)…",o:["El ejecutable es más pequeño y la librería se comparte en memoria, pero debe estar en la máquina","El código de la librería se copia dentro del ejecutable","El ejecutable es autónomo","El ejecutable ocupa más"],a:0,e:"Las estáticas (.a) se «cortan y pegan» dentro: ejecutable autónomo pero mayor (hola estático ≈ 800 KB frente a ≈ 10 KB).",w:{3:"Falso: las estáticas son las que hacen crecer el ejecutable."}},
{t:5,q:"¿Qué orden muestra las librerías dinámicas con las que enlaza un ejecutable?",o:["`ldd ejecutable`","`ld ejecutable`","`ls -l ejecutable`","`gdb ejecutable`"],a:0,e:"Para hola aparece, entre otras, libc.so.6 (la librería estándar de C, donde está puts)."},
{t:5,q:"Para obtener un ejecutable estático con gcc se usa la opción…",o:["`-static`","`-g`","`-S`","`-lm`"],a:0,e:"-g añade información de depuración para gdb; -lm enlaza la librería matemática."},
{t:5,q:"En la sintaxis AT&T, `add %rbx, %rax` hace…",o:["RAX = RAX + RBX","RBX = RBX + RAX","RAX = RBX","RBX = RAX + RBX + 1"],a:0,e:"El resultado queda en el segundo operando (destino)."},
{t:5,q:"En `mov $1234, %rax`, el `$` indica que 1234 es…",o:["Una constante (inmediato) dentro de la propia instrucción","Una dirección de memoria","Un registro","Una etiqueta"],a:0,e:"Los registros llevan % y los inmediatos $. Un número sin $ sería una dirección de memoria."},
{t:5,q:"`mov (%rbx), %rax` hace…",o:["RAX := contenido de la memoria en la dirección RBX","RAX := RBX","RBX := RAX","RAX := dirección de RBX"],a:0,e:"Los paréntesis indican acceso a memoria (Mem[RBX])."},
{t:5,q:"En x86-64, EAX es…",o:["Los 32 bits inferiores de RAX","Los 16 bits inferiores de RAX","Un registro distinto de RAX","Los 8 bits superiores de AX"],a:0,e:"RAX 64 bits → EAX 32 → AX 16 → AL 8 (y AH los 8 siguientes)."},
{t:5,q:"El registro RIP de x86-64 es…",o:["El puntero de instrucción (el PC)","El puntero de pila","El registro de estado","Un registro de punto flotante"],a:0,e:"RSP es el puntero de pila, RBP el puntero base y RFLAGS el de estado (lo usan los saltos condicionales)."},
{t:5,q:"¿Dónde se guarda el resultado de una comparación `cmp` para que la use el salto condicional?",o:["En RFLAGS (registro de estado)","En RAX","En la pila","En RIP"],a:0,e:"cmp modifica los flags y je, jne, jg, jge, jl, jle deciden según ellos."},
{t:5,q:"`cmp $5, %rax` seguido de `jge .L1` salta a .L1 si…",o:["RAX ≥ 5","5 ≥ RAX","RAX = 5","RAX < 5"],a:0,e:"En AT&T se compara el segundo operando con el primero: «RAX comparado con 5»."},
{t:5,q:"`array(,%rax,4)` es la dirección…",o:["array + RAX · 4","array · 4 + RAX","RAX + 4","array + 4"],a:0,e:"Cada int ocupa 4 bytes, así que el elemento i está en array + 4i."},
{t:5,q:"¿Qué hace la instrucción `call misubrutina`?",o:["Guarda la dirección de retorno en la pila y salta a la subrutina","Salta sin guardar nada","Guarda RAX en la pila","Vuelve de la subrutina"],a:0,e:"ret recupera de la pila la dirección de retorno y la pone en RIP."},
{t:5,q:"La pila es una estructura…",o:["LIFO (Last In, First Out) que en x86-64 crece hacia direcciones bajas","FIFO que crece hacia direcciones altas","De acceso aleatorio dentro de la CPU","Que sólo guarda instrucciones"],a:0,e:"push guarda en la cima y pop la recupera. RSP apunta a la cima."},
{t:5,q:"Las variables locales de una función en C se guardan normalmente en…",o:["La pila","El segmento de datos (.data)","El registro RIP","La memoria ROM"],a:0,e:"Por ejemplo i en -4(%rbp). Las variables globales van en el segmento de datos."},
{t:5,q:"Las variables globales de un programa C aparecen en el ensamblador en…",o:["El segmento de datos (.data)","El segmento de código (.text)","La pila","Los registros"],a:0,e:"Con directivas como .long 10 (4 bytes con valor inicial 10)."},
{t:5,q:"RBP (base pointer)…",o:["Apunta a un lugar fijo del marco de pila de la rutina para acceder a parámetros y locales","Apunta siempre a la cima de la pila","Contiene la dirección de la siguiente instrucción","Guarda el resultado de las funciones"],a:0,e:"RSP sí cambia continuamente (call, ret, push, pop)."},
{t:5,q:"Según el ABI System V AMD64 (Linux), el primer parámetro entero de una función se pasa en…",o:["RDI (EDI si es de 32 bits)","RAX","La pila siempre","RSP"],a:0,e:"Orden: RDI, RSI, RDX, RCX, R8, R9; el resto por la pila. El resultado se devuelve en RAX/EAX."},
{t:5,q:"El sufijo «l» en `movl` indica un dato de…",o:["32 bits (long)","64 bits","16 bits","8 bits"],a:0,e:"q = quad (64), l = long (32), w = word (16), b = byte (8)."},
{t:5,q:"¿Qué hace `cltq`?",o:["Extiende el signo de EAX a RAX","Limpia RAX","Compara EAX con RAX","Convierte un entero a float"],a:0,e:"Se usa antes de calcular array + rax·4 con el índice i (de 32 bits)."},
{t:5,q:"Las instrucciones x86-64 son de longitud…",o:["Variable (CISC)","Fija de 32 bits","Fija de 64 bits","Fija de 8 bits"],a:0,e:"En el ejemplo, de 1 a 7 bytes (push %rbp = 55, 1 byte). En MIPS32 son siempre de 32 bits."},
{t:5,q:"Un `jmp` corto (2 bytes) está en 0xF y salta a 0x33. ¿Qué desplazamiento lleva codificado?",o:["0x22","0x24","0x33","0x11"],a:0,e:"Es relativo al PC siguiente: 0x33 − (0xF + 2) = 0x33 − 0x11 = 0x22 → eb 22."},
{t:5,q:"Un `jmp` corto en 0x40 salta a 0x2A. ¿Qué byte de desplazamiento lleva?",o:["0xE8 (−24 en C2)","0x18","0xEA","0x2A"],a:0,e:"0x2A − 0x42 = −0x18 = −24 → en C2 de 8 bits 256 − 24 = 232 = 0xE8. Los saltos hacia atrás son negativos."},
{t:5,q:"Al enlazar y cargar un programa, ¿por qué no cambia la codificación de un salto relativo como `eb 22`?",o:["Porque es relativo al PC: no depende de dónde se cargue el código","Porque el enlazador no toca el código","Porque los saltos no se ejecutan","Porque el código se carga en la dirección 0"],a:0,e:"En cambio, los accesos a variables globales (0x0(,%rax,4)) sí se reubican con la dirección definitiva."},
{t:5,q:"En memoria aparece la dirección de array 0x00601060 como los bytes `60 10 60 00`. Esto se debe a que x86-64 es…",o:["Little endian","Big endian","RISC","De 48 bits"],a:0,e:"El byte menos significativo (0x60) está en la dirección más baja."},
{t:5,q:"Si un array de float contiene `.long 1092616192` (0x41200000), el valor es…",o:["10,0","1092616192","4,0","2,5"],a:0,e:"Es la codificación IEEE 754 simple de 10,0 (1,01 × 2^3, e = 130). Los bits son los mismos: el tipo lo conoce el compilador."},
{t:5,q:"¿Cómo sabe el computador si unos bits de memoria son un carácter, un entero o un real?",o:["La memoria no lo sabe: lo sabe el compilador, que genera unas instrucciones u otras según el tipo","Por un bit de tipo en cada celda","Por la dirección donde están","Por el sistema operativo"],a:0,e:"Por eso un entero usa movl/imull y un float movss/mulss con los registros xmm."},
{t:5,q:"Los procesadores x86-64 actuales usan direcciones virtuales de…",o:["48 bits (256 TB), aunque el ISA define 64","64 bits completos","32 bits","16 bits"],a:0,e:"El hardware ignora por ahora los 16 bits de más peso: no hace falta tanta memoria."},
{t:5,q:"La MMU…",o:["Traduce las direcciones virtuales a físicas, dentro de la CPU","Es un tipo de memoria caché","Gestiona los procesos","Es el enlazador del SO"],a:0,e:"Gracias a la memoria virtual, cada programa ve su propio espacio de direcciones y el SO lo protege de los demás."},
{t:5,q:"En gdb, ¿qué orden ejecuta una sola instrucción ensamblador?",o:["`stepi`","`step`","`next`","`continue`"],a:0,e:"step y next avanzan una sentencia de C; continue sigue hasta el próximo breakpoint."},
{t:5,q:"En gdb, `x/40bx array` muestra…",o:["40 bytes en hexadecimal a partir de la dirección de array","El array en decimal","40 elementos enteros","La dirección de array"],a:0,e:"x = examinar memoria: 40 unidades de tamaño b (byte) en formato x (hex). Para el array en C: p array."},
{t:5,q:"Un array de 10 int empieza en 0x601040. ¿Dirección de su último elemento?",o:["0x601064","0x601049","0x60104A","0x601068"],a:0,e:"0x601040 + 9 · 4 = 0x601040 + 36 = 0x601040 + 0x24."},
{t:5,q:"¿Qué ocurre en una recursión infinita?",o:["La pila crece hasta superar su límite y el programa termina (stack overflow)","El programa se ejecuta para siempre sin consumir memoria","Se llena el disco","El SO añade más pila sin límite"],a:0,e:"Cada call guarda la dirección de retorno y el marco en la pila. El límite se ve con ulimit -a."},
{t:5,q:"Un programa termina con `return 63;`. ¿Cómo lo compruebas desde bash?",o:["`echo $?`","`echo $PATH`","`ps -Af`","`ldd programa`"],a:0,e:"$? guarda el estado de salida (los 8 bits menos significativos del valor devuelto por main)."},
/* ---------------- TEMA 6 · Redes de ordenadores ---------------- */
{t:6,q:"Internet es…",o:["Un conjunto descentralizado de redes interconectadas que usan TCP/IP","Una única red física mundial","Un servidor central de páginas web","Un protocolo de transporte"],a:0,e:"Redes físicas heterogéneas funcionan como una red lógica única. Su origen es ARPANET (1969)."},
{t:6,q:"Los dispositivos que reenvían y procesan paquetes en Internet son…",o:["Routers y conmutadores (switches)","Hosts","Módems","Servidores web"],a:0,e:"Los hosts o sistemas finales ejecutan las aplicaciones de red en el extremo de la red."},
{t:6,q:"En el modelo peer to peer (P2P)…",o:["Los equipos se comunican como iguales, sin un servidor central fijo","Siempre hay un servidor encendido que atiende a los clientes","Sólo hay dos equipos","El navegador es el servidor"],a:0,e:"Ej.: BitTorrent, Skype. Cliente-servidor: navegador y servidor web, cliente y servidor de correo."},
{t:6,q:"Un protocolo define…",o:["El formato y el orden de los mensajes y las acciones al enviarlos y recibirlos","Sólo la velocidad del enlace","El cableado de la red","El sistema operativo de cada equipo"],a:0,e:"Igual que un protocolo humano: saludar, preguntar, responder."},
{t:6,q:"La arquitectura de red (pila de protocolos) es…",o:["El conjunto de capas y de protocolos usados en cada capa","El conjunto de routers de Internet","El cableado de un edificio","El conjunto de servidores DNS"],a:0,e:"Cada capa da servicios a la superior usando sólo los de la inferior. Las entidades de la misma capa en distintos hosts son procesos pares."},
{t:6,q:"¿En qué capa de Internet está HTTP?",o:["Aplicación","Transporte","Red","Enlace"],a:0,e:"También FTP, SMTP, POP3, DNS y BitTorrent."},
{t:6,q:"¿Qué capa se encarga del encaminamiento de los paquetes desde el origen al destino?",o:["Red (IP)","Transporte","Enlace","Física"],a:0,e:"La capa de red usa IP y algoritmos de encaminamiento a través de routers."},
{t:6,q:"Ethernet (IEEE 802.3) y WiFi (IEEE 802.11) son protocolos de la capa…",o:["De enlace","De red","De transporte","De aplicación"],a:0,e:"Transfieren datos entre elementos conectados directamente. Otros: PPP, HDLC."},
{t:6,q:"Sobre TCP es cierto que…",o:["Es orientado a conexión y fiable: datos sin errores y en orden","No es fiable y se usa para vídeo en tiempo real","Es un protocolo de la capa de red","No usa puertos"],a:0,e:"UDP es no orientado a conexión y no fiable; muy usado para audio y vídeo en tiempo real.",w:{1:"Eso describe a UDP."}},
{t:6,q:"UDP es…",o:["No orientado a conexión y no fiable","Orientado a conexión y fiable","Un protocolo de aplicación","El protocolo del Web"],a:0,e:"Trampa típica: lo fiable y orientado a conexión es TCP."},
{t:6,q:"La capa de transporte distingue las aplicaciones de una misma máquina mediante…",o:["Los puertos","Las direcciones IP","Las direcciones MAC","Las URL"],a:0,e:"Cada proceso de un equipo se identifica con un número de puerto."},
{t:6,q:"Encapsulación: al bajar por las capas en el origen…",o:["Cada capa añade su cabecera a lo que recibe de arriba","Cada capa quita una cabecera","Sólo la capa física añade información","Los datos no cambian"],a:0,e:"Mensaje → segmento TCP/UDP → datagrama IP → trama Ethernet/WiFi. En el destino cada capa quita la suya."},
{t:6,q:"Una dirección IPv4 tiene…",o:["32 bits, escritos como 4 números de 0 a 255","64 bits","48 bits, en hexadecimal","128 bits"],a:0,e:"Ej.: 10000000 00001011 00000011 00011111 = 128.11.3.31. (48 bits es una MAC; 128, IPv6.)"},
{t:6,q:"Una dirección IP se divide en…",o:["Dirección de red (netid) y dirección de host (hostid)","Puerto y protocolo","Máscara y puerta de enlace","Nombre y dominio"],a:0,e:"Todas las interfaces de la misma red comparten el netid."},
{t:6,q:"El organismo responsable de la asignación de direcciones IP es…",o:["La ICANN","El IEEE","La RAE","La W3C"],a:0,e:"Internet Corporation for Assigned Names and Numbers."},
{t:6,q:"La máscara /20 en decimal con puntos es…",o:["255.255.240.0","255.255.255.240","255.240.0.0","255.255.224.0"],a:0,e:"20 unos: 8 + 8 + 4 → el tercer byte es 11110000 = 240."},
{t:6,q:"La máscara /26 es…",o:["255.255.255.192","255.255.255.224","255.255.255.128","255.255.192.0"],a:0,e:"8 + 8 + 8 + 2 → el último byte es 11000000 = 192."},
{t:6,q:"¿Cuál es la dirección de red de 155.54.12.219/20?",o:["155.54.0.0","155.54.12.0","155.54.15.255","155.54.12.219"],a:0,e:"IP AND máscara. Tercer byte 12 = 0000 1100: sus 4 primeros bits (de red) son 0000 → 155.54.0.0."},
{t:6,q:"¿Cuál es la dirección de broadcast de 155.54.12.219/20?",o:["155.54.15.255","155.54.255.255","155.54.12.255","155.54.0.255"],a:0,e:"Hostid (12 bits) a 1: tercer byte 0000 1111 = 15 y el cuarto 255."},
{t:6,q:"¿Cuántos hosts caben en una red /20?",o:["4094","4096","1024","65534"],a:0,e:"2^(32−20) = 4096 direcciones, menos la de red y la de broadcast."},
{t:6,q:"¿Cuántos hosts caben en una red /26?",o:["62","64","30","126"],a:0,e:"2^6 − 2 = 62."},
{t:6,q:"¿Están en la misma red 192.168.1.130/26 y 192.168.1.60/26?",o:["No: la primera está en la red .128 y la segunda en la .0","Sí, porque empiezan por 192.168.1","Sí, porque tienen la misma máscara","No se puede saber sin la puerta de enlace"],a:0,e:"130 = 10000010 → red .128; 60 = 00111100 → red .0. Los netid son distintos: A enviará los paquetes para B a su router por defecto."},
{t:6,q:"Un equipo tiene IP 155.54.223.216 y máscara 255.255.255.224. ¿A qué subred pertenece?",o:["155.54.223.192/27","155.54.223.0/24","155.54.223.216/27","155.54.223.224/27"],a:0,e:"224 = 11100000 → /27. 216 = 11011000 AND 11100000 = 11000000 = 192. Broadcast: 155.54.223.223."},
{t:6,q:"Una dirección IP con el hostid todo a 1 es…",o:["La dirección de difusión (broadcast) de la red","La dirección de la propia red","La del router por defecto","Una dirección de host normal"],a:0,e:"Hostid todo a 0 = dirección de red. Ninguna de las dos se puede asignar a un host."},
{t:6,q:"Si el host destino está en otra red, el origen envía el paquete…",o:["A su router por defecto (gateway), con la IP del host destino","Directamente al destino","Al servidor DNS","A la dirección de broadcast"],a:0,e:"La IP de destino del paquete sigue siendo la del host destino, no la del router.",w:{1:"Sólo se envía directamente si los dos están en la misma red (mismo netid)."}},
{t:6,q:"¿Qué tres valores necesita un host para su configuración IP?",o:["Su IP, la máscara de subred y la IP del router por defecto","Su MAC, su puerto y su nombre","Su IP, su puerto y la URL","La IP del servidor web, la del DNS y la del router"],a:0,e:"Se pueden configurar a mano o automáticamente con DHCP."},
{t:6,q:"DHCP sirve para…",o:["Asignar automáticamente la IP, la máscara y el router por defecto","Traducir nombres a direcciones IP","Transferir ficheros","Cifrar la conexión"],a:0,e:"Dynamic Host Configuration Protocol. Traducir nombres es tarea del DNS.",w:{1:"Eso es el DNS."}},
{t:6,q:"Una conexión de transporte queda identificada por…",o:["IP de origen, IP de destino, puerto de origen y puerto de destino","Sólo la IP de destino","La IP de origen y la URL","La MAC y el puerto"],a:0,e:"Así un servidor web distingue varias conexiones al mismo puerto 80."},
{t:6,q:"Dos clientes con la misma IP se conectan al puerto 80 del mismo servidor. ¿Cómo se distinguen sus conexiones?",o:["Por el puerto de origen","Por la IP de destino","Por el puerto de destino","No se pueden distinguir"],a:0,e:"Los cuatro valores sólo se diferencian en el puerto de origen (p. ej. 9157 y 5775)."},
{t:6,q:"¿Qué puerto usa habitualmente un servidor HTTP?",o:["80","443","22","53"],a:0,e:"HTTPS 443, SSH 22, DNS 53, FTP 21, SMTP 25, POP3 110."},
{t:6,q:"El DNS…",o:["Traduce nombres de host en direcciones IP; usa UDP y el puerto 53","Asigna direcciones IP a los equipos","Es el protocolo del Web","Usa TCP en el puerto 80"],a:0,e:"Es una base de datos distribuida en una jerarquía de servidores. También hace traducciones inversas y gestiona alias."},
{t:6,q:"En la URL `http://www.someschool.edu/someDept/pic.gif`, `www.someschool.edu` es…",o:["El nombre del host","El protocolo","La ruta del objeto","El puerto"],a:0,e:"protocolo :// nombre del host / trayectoria (ruta)."},
{t:6,q:"HTTP es un protocolo…",o:["Sin estado: el servidor no recuerda las peticiones anteriores","Con estado: guarda las conexiones anteriores","De transporte","Que usa UDP"],a:0,e:"Sigue el modelo cliente-servidor y usa TCP como transporte."},
{t:6,q:"En una petición HTTP, ¿qué marca el final del mensaje?",o:["Una línea en blanco","La palabra END","El código 200","Cerrar la conexión TCP"],a:0,e:"Línea de solicitud (GET /ruta HTTP/1.1), cabeceras «campo: valor» y una línea en blanco."},
{t:6,q:"El código de respuesta HTTP 404 significa…",o:["El objeto solicitado no existe en el servidor","Todo correcto","El objeto se ha movido","Error interno del servidor"],a:0,e:"200 OK, 301 Moved Permanently, 400 Bad Request, 404 Not Found, 500 error del servidor."},
{t:6,q:"En una respuesta HTTP, la cabecera `Content-Length: 321` indica…",o:["El tamaño en bytes del objeto enviado","El número de líneas","El tiempo de respuesta","El puerto usado"],a:0,e:"Content-Type indica el tipo (text/html, text/plain…)."},
{t:6,q:"¿Qué orden de Linux muestra la IP y la máscara de las interfaces de red?",o:["`ifconfig`","`route`","`host`","`ping`"],a:0,e:"route -n muestra la tabla de rutas (router por defecto), host consulta el DNS y ping comprueba si un host responde."},
{t:6,q:"La interfaz `lo` con IP 127.0.0.1 es…",o:["El dispositivo de bucle local (loopback): tráfico del equipo hacia sí mismo","La tarjeta Ethernet","La tarjeta WiFi","El router"],a:0,e:"Es una interfaz virtual."},
{t:6,q:"En la salida de `route -n`, la entrada con destino 0.0.0.0 indica…",o:["La ruta por defecto: el router (pasarela) para cualquier otra red","La propia red local","Una red sin conexión","La dirección de broadcast"],a:0,e:"Las redes con pasarela 0.0.0.0 se alcanzan directamente, sin router."},
{t:6,q:"¿Qué orden lista las conexiones TCP y UDP activas con el programa que las abrió?",o:["`netstat -tupan`","`ifconfig -a`","`ps -Af`","`host -a`"],a:0,e:"-t TCP, -u UDP, -a todas (también en escucha), -n puertos numéricos, -p PID y programa."},
{t:6,q:"Con `telnet www.ditec.um.es 80`…",o:["Se abre una conexión TCP al puerto 80 y se puede escribir a mano la petición HTTP","Se descarga la página automáticamente","Se consulta el DNS","Se comprueba si el host responde con ICMP"],a:0,e:"Después se teclea, p. ej., GET / HTTP/1.1, Host: www.ditec.um.es y una línea en blanco."}
];
BANK.forEach((b,i)=>{b.id=i;});

const TOPICS = {
  1:{name:"Introducción",desc:"Von Neumann, buses, memoria, endianness, unidades, rendimiento, placa base, overclocking e historia."},
  2:{name:"Representación de la información",desc:"Bases, enteros (SM, sesgada, C2), octal y hexadecimal, IEEE 754, ASCII, Unicode e imágenes."},
  3:{name:"Circuitos combinacionales",desc:"Álgebra de Boole, Karnaugh, puertas, retardos, NAND/NOR, decodificadores, MUX, ROM y sumadores."},
  4:{name:"Sistemas operativos (Linux)",desc:"Concepto y tipos de SO, procesos, ficheros, permisos, comandos, redirecciones, arranque e interrupciones."},
  5:{name:"Lenguajes del computador",desc:"Instrucciones, compilación y enlazado, librerías, x86-64, pila, codificación y reubicación."},
  6:{name:"Redes de ordenadores",desc:"Internet, capas y protocolos, TCP/UDP, IP y CIDR, puertos, DNS y HTTP."}
};
const TOPIC_IDS = {1:[],2:[],3:[],4:[],5:[],6:[]};
BANK.forEach(b=>TOPIC_IDS[b.t].push(b.id));
const GENERAL_MIX = {1:5,2:6,3:6,4:5,5:4,6:4}; // 30 preguntas

  Object.assign(FC, { BANK, TOPICS, TOPIC_IDS, GENERAL_MIX });
})(window.FC = window.FC || {});
